-- Cat Parts Store fuel-system references with explicit marine compatible models.
on conflict (part_number) do nothing;

update public.part_catalog
set technical_group='موتورهای دریایی - سیستم سوخت',
 application_type='BOTH',
 application_evidence='Official Cat Compatible Models lists Marine Engine and/or Marine Auxiliary alongside non-marine engine, generator, industrial, petroleum, locomotive or other applications.',
 application_source_url='https://parts.cat.com/en/catcorp/product/'||part_number,
 updated_at=now()
where part_number in ('210-2535','273-3286','210-1471','264-8859','20R-1270','392-0214','20R-1275','9D-2734','264-6416','306-6820','392-0220','237-2719','595-3920','250-1306','392-0206','2W-6290');
